def bookend(ranked):
    """Return the items of `ranked` (best first) in bookend order.

    The best item comes first, the second-best last, and the rest in between in rank order.
    The input list is not modified.
    """
    if len(ranked) < 3:
        return list(ranked)
    return [ranked[0]] + ranked[2:] + [ranked[1]]
